import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"Events","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/storage/events.md","filePath":"en/modules/storage/events.md","lastUpdated":0}`),a={name:`en/modules/storage/events.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to “Events”">​</a></h1><p>Storage events live in <code>emaki.jiuwu.craft.storage.api.event</code>. All four are synchronous cancellable Bukkit events published on the storage owner&#39;s owner thread. Their fields are immutable transaction snapshots and no mutable business field is exposed</p><table tabindex="0"><thead><tr><th>Event</th><th>Timing</th><th>Cancellation effect</th><th>Runtime path</th></tr></thead><tbody><tr><td><code>StorageDepositEvent</code></td><td>After the capacity pre-check, before inventory removal (when there is one) and the entry credit</td><td>Blocks the removal and the storage increase</td><td>The transaction deposit and <code>depositDirect</code>, including <code>depositAsync(..., source=api)</code>, the GUI, commands and actions</td></tr><tr><td><code>StorageWithdrawEvent</code></td><td>After the withdrawable amount is computed, before the entry debit and the item delivery</td><td>Blocks the debit and the delivery</td><td><code>StorageTransactionService.withdraw</code>, including <code>withdrawAsync(..., source=api)</code>, the GUI, commands and actions</td></tr><tr><td><code>StorageUnlockEvent</code></td><td>After the total price is computed, before any currency or item charge and the purchased-slot increase</td><td>Blocks every charge and the unlock</td><td>The paid unlock service; the admin <code>grantSlotsAsync</code> does not fire it</td></tr><tr><td><code>StorageBatchEvent</code></td><td>Before a batch operation commits, ahead of any escrow debit or write</td><td>Aborts the whole batch; no per-op Deposit/Withdraw event is fired inside a batch</td><td><code>applyBatchAsync</code></td></tr></tbody></table><p>The payload is fixed per event: deposit, withdraw and unlock carry <code>playerId()</code>, a cloned and normalised <code>template()</code>, <code>requestedAmount()</code> and <code>source()</code>; withdraw adds <code>storedAmount()</code>; unlock carries <code>slotAmount()</code>, <code>purchasedSlotsBefore()</code> and <code>currencyCost()</code> (<strong>currency only</strong> — an item price is not reflected in this event). <code>StorageBatchEvent</code> carries <code>playerId()</code>, the op list (<code>ops()</code> returns an immutable <code>List&lt;StorageBatchOp&gt;</code> whose templates are copies with <code>amount == 1</code>), the <code>allOrNothing()</code> flag and <code>source()</code>. Accessors are record-style without a <code>get</code> prefix. Threading contract: the asynchronous facade only submits and dispatches; the event still fires synchronously inside the real owner-thread transaction, and a future callback does not inherit that thread guarantee</p><p><code>source</code> is a runtime surface id with exactly 5 possible values: <code>gui</code> / <code>command</code> / <code>api</code> / <code>action</code> / <code>auto_pickup</code>. Of these, <code>auto_pickup</code> only ever appears on deposit events (auto-pickup goes through the direct deposit path); <code>StorageUnlockEvent</code> currently only ever carries <code>gui</code>, because paid expansion has no entry point in this plugin other than the GUI</p><p>Emission rule: these events are emitted by the runtime transaction paths. No synthetic event is published when the bridge is unavailable; the future-returning facade operations report explicit result failures instead</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};